import React, { useEffect, useRef, memo } from 'react';

const TickerTape = () => {
  const containerRef = useRef(null);

  useEffect(() => {
    const container = containerRef.current;
    if (!container) return;

    // Clean up any previous render
    container.innerHTML = '';

    const widgetDiv = document.createElement('div');
    widgetDiv.className = 'tradingview-widget-container__widget';
    container.appendChild(widgetDiv);

    const script = document.createElement('script');
    script.type = 'text/javascript';
    script.src =
      'https://s3.tradingview.com/external-embedding/embed-widget-ticker-tape.js';
    script.async = true;

    // Config is set as the script's text content — this is the official TradingView method
    script.innerHTML = JSON.stringify({
      symbols: [
        // CAPITALCOM:IN50 is a CFD for Nifty 50 — no widget licensing block
        { description: 'NIFTY 50',   proName: 'CAPITALCOM:IN50'   },
        { description: 'SENSEX',     proName: 'CAPITALCOM:IN30'   },
        { description: 'BANK NIFTY', proName: 'CAPITALCOM:NIFTY_BANK' },
        { description: 'NIFTY IT',   proName: 'NSE:CNXIT'         },
        { description: 'Gold',       proName: 'TVC:GOLD'          },
        { description: 'USD/INR',    proName: 'FX_IDC:USDINR'     },
        { description: 'Crude Oil',  proName: 'TVC:USOIL'         },
      ],
      showSymbolLogo: true,
      isTransparent: false,
      displayMode: 'adaptive',
      colorTheme: 'light',
      locale: 'in',
    });

    container.appendChild(script);

    return () => {
      container.innerHTML = '';
    };
  }, []);

  return (
    <div
      ref={containerRef}
      className="tradingview-widget-container"
      style={{
        width: '100%',
        overflow: 'hidden',
        borderTop: '2px solid var(--accent-teal)',
        margin: '40px 0 20px 0',
      }}
    />
  );
};

export default memo(TickerTape);
